(()=>{const c=document.querySelector('#board'),ctx=c.getContext('2d'),status=document.querySelector('#status'),overlay=document.querySelector('#overlay'),s1=document.querySelector('#p1score'),s2=document.querySelector('#p2score'),modeBtn=document.querySelector('#mode'),p2pad=document.querySelector('#p2pad');const W=c.width,H=c.height;let p1=H/2-38,p2=H/2-38,ball={x:W/2,y:H/2,vx:4,vy:2.5},a=0,b=0,playing=false,two=false,keys={},raf;function draw(){ctx.fillStyle='#171e24';ctx.fillRect(0,0,W,H);ctx.setLineDash([8,12]);ctx.strokeStyle='#ffffff2b';ctx.beginPath();ctx.moveTo(W/2,12);ctx.lineTo(W/2,H-12);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#8fc4aa';ctx.fillRect(22,p1,10,76);ctx.fillStyle='#bd8790';ctx.fillRect(W-32,p2,10,76);ctx.fillStyle='#c4b998';ctx.shadowColor='#c4b998';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(ball.x,ball.y,8,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}function movePaddles(){if(keys.w)p1=Math.max(0,p1-6);if(keys.s)p1=Math.min(H-76,p1+6);if(two){if(keys.ArrowUp)p2=Math.max(0,p2-6);if(keys.ArrowDown)p2=Math.min(H-76,p2+6)}else{let center=p2+38;if(center<ball.y-12)p2=Math.min(H-76,p2+4.3);if(center>ball.y+12)p2=Math.max(0,p2-4.3)}}function loop(){if(!playing)return;movePaddles();ball.x+=ball.vx;ball.y+=ball.vy;if(ball.y<9||ball.y>H-9)ball.vy*=-1;if(ball.vx<0&&ball.x<38&&ball.x>20&&ball.y>p1-8&&ball.y<p1+84){ball.vx=Math.abs(ball.vx)*1.04;ball.vy+=((ball.y-(p1+38))/38)*2.5;ball.x=39}if(ball.vx>0&&ball.x>W-38&&ball.x<W-20&&ball.y>p2-8&&ball.y<p2+84){ball.vx=-Math.abs(ball.vx)*1.04;ball.vy+=((ball.y-(p2+38))/38)*2.5;ball.x=W-39}if(ball.x<-8){b++;s2.textContent=b;point('Point for '+(two?'Player 2':'the computer')+'!')}if(ball.x>W+8){a++;s1.textContent=a;point('Point for Player 1!')}draw();raf=requestAnimationFrame(loop)}function point(msg){if(a>=7||b>=7){playing=false;cancelAnimationFrame(raf);const winner=a>b?'Player 1':(two?'Player 2':'Computer');status.textContent=winner+' wins! Start a new match to play again.';overlay.querySelector('h2').textContent=winner+' wins!';overlay.querySelector('p').textContent='Final score: '+a+' — '+b+'.';overlay.style.display='grid';return}ball={x:W/2,y:H/2,vx:(a>b?1:-1)*4*(Math.random()>.5?1:-1),vy:(Math.random()*4-2)||2};status.textContent=msg+' Serve!';draw()}function start(){if(playing)return;overlay.style.display='none';playing=true;status.textContent='Rally!';loop()}function reset(){cancelAnimationFrame(raf);playing=false;a=b=0;p1=p2=H/2-38;s1.textContent=s2.textContent='0';ball={x:W/2,y:H/2,vx:4,vy:2.5};status.textContent='First to 7. Press start to rally!';overlay.querySelector('h2').textContent='Ready to rally?';overlay.querySelector('p').textContent='Player one serves first.';overlay.style.display='grid';draw()}document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key===' '&&!playing)start()});document.addEventListener('keyup',e=>keys[e.key]=false);document.querySelector('#start').onclick=start;document.querySelector('#overlay-start').onclick=start;document.querySelector('#restart').onclick=reset;modeBtn.onclick=()=>{two=!two;modeBtn.textContent='Mode: '+(two?'2 players':'1 player');p2pad.style.display=two?'grid':'none';reset()};document.querySelectorAll('[data-move]').forEach(btn=>{const key=btn.dataset.move;const map={p1up:'w',p1down:'s',p2up:'ArrowUp',p2down:'ArrowDown'};btn.onpointerdown=e=>{e.preventDefault();keys[map[key]]=true};btn.onpointerup=btn.onpointerleave=()=>keys[map[key]]=false});c.addEventListener('touchstart',e=>{const r=c.getBoundingClientRect(),y=e.touches[0].clientY-r.top,mid=r.height/2;if(y<mid)keys.w=true;else keys.s=true},{passive:true});c.addEventListener('touchend',()=>{keys.w=keys.s=false},{passive:true});reset()})();
